package com.yigongbao.backup.cold;
import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class ColdBatchWorkflowServiceTest { @Test void stateFlowRequiresVerification(){var mapper=mock(ColdBatchMapper.class);var b=new ColdBatchEntity();b.setId(1L);b.setStatus("CREATED");b.setVersion(0);when(mapper.selectById(1L)).thenReturn(b);when(mapper.updateById(any(ColdBatchEntity.class))).thenReturn(1);var s=new ColdBatchWorkflowService(mapper);assertThat(s.start(1).getStatus()).isEqualTo("WRITING");b.setStatus("WRITING");assertThat(s.complete(1,1,2,3,"h").getStatus()).isEqualTo("COMPLETED");b.setStatus("COMPLETED");assertThat(s.verify(1).getStatus()).isEqualTo("VERIFIED");b.setStatus("VERIFIED");b.setHotCleanupStatus("READY");assertThat(s.markHotCleaned(1).getHotCleanupStatus()).isEqualTo("CLEANED");} }
